def tags(p): return '<div class="tags">'+''.join('<span>'+x+'</span>' for x in p['tags'])+'</div>'
def explore(p): return f'<button class="text-btn" data-project="{p["id"]}">Explore project <span aria-hidden="true">↗</span></button>'
def alternate(): return '''<section class="other-panel" data-panel="experience" hidden><h2>Experience</h2><p>Fullstack development, cloud infrastructure, and the work in between.</p><div class="empty"><h3>Experience details are being prepared.</h3><p>For now, explore the projects for a closer look at the work, or connect on LinkedIn.</p><button class="btn" data-switch="projects">Browse projects</button></div></section><section class="other-panel" data-panel="writing" hidden><h2>Notes from building</h2><p>Short observations on making software easier to run and maintain.</p><article class="writing-item"><span class="demo">Sample writing</span><h3>Small systems, good habits.</h3><p>Clear logs, reversible changes, and a little documentation go a long way.</p><span class="small muted">September 1, 2026</span><br><button class="text-btn" data-modal="writing">Read the note ↗</button></article></section><section class="other-panel" data-panel="about" hidden><h2>Hello, I’m Rizki.</h2><p>I’m interested in turning ideas into useful things, from the interface to the infrastructure behind it.</p><p>From a small idea to something that works.</p><button class="btn primary" data-modal="contact">Let’s connect</button></section>'''

notes={'a':('A · Refined personal feed','Struktur profil dan feed dipertahankan. Teks pendukung diperbesar, tombol minimal 44 px, dan aksi proyek lebih jelas agar halaman lebih mudah dibaca tanpa mengubah identitasnya.'),'b':('B · Work comes first','Profil pindah ke sisi kiri di desktop. Proyek unggulan mendapat ruang terbesar; proyek lain lebih ringkas. Tujuannya mempercepat penilaian karya sambil menjaga akses kontak.'),'c':('C · The working studio','Pilih proyek untuk mengganti panggung demo. Palet biru diperluas untuk memberi kesan ruang kerja teknis. Interaksi menunjukkan gagasan proyek sebelum pengunjung membuka detailnya.')}

JS = r'''
const root=document.documentElement;
let themeChoice=null;
function setTheme(t){root.dataset.theme=t;document.querySelectorAll('.theme').forEach(b=>{b.textContent=t==='dark'?'☼':'☾';b.setAttribute('aria-label','Switch to '+(t==='dark'?'light':'dark')+' theme')})}
try{themeChoice=localStorage.getItem('exploration-theme')}catch{}
const systemTheme=matchMedia('(prefers-color-scheme: dark)');
setTheme(['light','dark'].includes(themeChoice)?themeChoice:systemTheme.matches?'dark':'light');
systemTheme.addEventListener('change',e=>{if(!themeChoice)setTheme(e.matches?'dark':'light')});
document.querySelectorAll('.theme').forEach(b=>b.onclick=()=>{themeChoice=root.dataset.theme==='dark'?'light':'dark';setTheme(themeChoice);try{localStorage.setItem('exploration-theme',themeChoice)}catch{}});
window.addEventListener('message',e=>{if(e.source===parent&&e.data?.type==='exploration-theme'&&['light','dark'].includes(e.data.theme))setTheme(e.data.theme)});
function switchTab(tab){document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tab===tab)));document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==tab)}
document.querySelectorAll('[data-tab],[data-switch]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab||b.dataset.switch));
const dialog=document.querySelector('dialog'),dialogContent=document.querySelector('#dialog-content'),dialogTitle=document.querySelector('#dialog-title');
const projectData={mail:{title:'Mailriz',summary:'Persistent email aliases on your own domain, built on Cloudflare.',problem:'Separate addresses are useful for work, shopping, and personal messages. Managing a different mailbox for each one creates unnecessary overhead.',approach:'Keep the aliases persistent and route incoming messages into one place. This concept uses a calm inbox and visible alias labels to keep the source of each message clear.',stack:'Cloudflare · TypeScript · D1 + R2',note:'The repository description supports the project overview. Contribution details and measured outcomes still need confirmation from the owner.'},storage:{title:'Cloud drive for macOS',summary:'Object storage, where you already work.',problem:'Moving between a storage dashboard and a local file browser interrupts everyday file management.',approach:'Mount a cloud-backed folder through SMB so files can be browsed in Finder. Connection status stays close to the folder.',stack:'JuiceFS · Redis · Docker',note:'Concept project for this design exploration. Not a verified portfolio achievement.'},agent:{title:'Agent relay',summary:'Know when the work is ready for you.',problem:'Checking a terminal repeatedly makes it harder to focus on something else while an agent is running.',approach:'Send a compact notification when a task finishes, with a clear result and enough context to pick up the work.',stack:'TypeScript · Automation',note:'Concept project for this design exploration. Not a verified portfolio achievement.'}};
let opener;
function openDialog(title,html){opener=document.activeElement;dialogTitle.textContent=title;dialogContent.innerHTML=html;dialog.showModal();document.body.style.overflow='hidden'}
dialog.addEventListener('close',()=>{document.body.style.overflow='';opener?.focus()});
document.querySelector('#close-dialog').onclick=()=>dialog.close();
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>showProject(b.dataset.project));
function showProject(id){const p=projectData[id];openDialog(p.title,`<p>${p.summary}</p><div class="detail-facts"><div><span>Project focus</span><strong>${id==='mail'?'Custom-domain email':id==='storage'?'Cloud file access':'Developer workflow'}</strong></div><div><span>Technology</span><strong>${p.stack}</strong></div></div><h3>The problem</h3><p>${p.problem}</p><h3>The approach</h3><p>${p.approach}</p><h3>${id==='mail'?'What still needs documenting':'Concept scope'}</h3><p>${p.note}</p>${id==='mail'?'<a class="btn primary" href="https://github.com/rizkirmdhnnn/mailriz" target="_blank" rel="noreferrer">View repository ↗</a>':''}`)}
const dialogs={contact:['Let’s connect',`<p>Have an idea, an opportunity, or just want to say hello?</p><a class="channel" href="https://www.linkedin.com/in/achmadrizkirmdhn/" target="_blank" rel="noreferrer"><strong>Connect on LinkedIn ↗</strong><span>For opportunities and conversations</span></a><a class="channel" href="https://github.com/rizkirmdhnnn" target="_blank" rel="noreferrer"><strong>Find me on GitHub ↗</strong><span>Explore code and open-source projects</span></a>`],cv:['Curriculum vitae',`<p class="small">Sample preview for this exploration. Employment history is intentionally left unfilled.</p><div class="cv-sheet"><h3>Achmad Rizki Ramadhan</h3><p>Fullstack & cloud<br>Yogyakarta, Indonesia</p><h3>Profile</h3><p>Building applications, connecting cloud infrastructure, and solving problems with AI.</p><h3>Selected project</h3><p><strong>Mailriz</strong><br>Persistent email aliases on your own domain.<br>Cloudflare / TypeScript / D1 + R2</p><h3>Focus</h3><p>Fullstack development<br>Cloud & DevOps<br>AI-assisted building</p></div><p class="small" style="margin-top:18px">The final site should use the owner’s published PDF.</p>`],writing:['Small systems, good habits.',`<p class="small">Sample writing · September 1, 2026</p><h3>Start with visibility</h3><p>Before adding infrastructure, make sure you can understand what is happening in the application. Clear logs and a simple health check are useful first steps.</p><h3>Make changes reversible</h3><p>Small deployments, documented configuration, and a rollback path reduce uncertainty when releasing changes.</p><h3>Document the reasoning</h3><p>Record why a decision was made, as well as how to run the system. That context helps when requirements change.</p>`]};
document.querySelectorAll('[data-modal]').forEach(b=>b.onclick=()=>openDialog(...dialogs[b.dataset.modal]));
document.querySelectorAll('.pick').forEach(b=>b.onclick=()=>{const id=b.dataset.pick;document.querySelectorAll('.pick').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-stage]').forEach(x=>x.hidden=x.dataset.stage!==id);const p=projectData[id];document.querySelector('#bench-title').textContent=p.title;document.querySelector('#bench-desc').textContent=p.summary;document.querySelector('#bench-explore').dataset.project=id;document.querySelector('#stage-label').textContent=id==='mail'?'Interactive inbox concept':'Concept project preview';document.querySelector('#selection-status').textContent=p.title+' selected.'});
const simulate=document.querySelector('#simulate-mail');
if(simulate)simulate.onclick=()=>{const arrived=simulate.dataset.arrived==='true';simulate.dataset.arrived=String(!arrived);document.querySelector('#new-mail').hidden=arrived;document.querySelector('#mail-count').textContent=arrived?'3 messages':'4 messages';document.querySelector('#mail-status').textContent=arrived?'All aliases connected':'Message received at hello@your.domain';simulate.textContent=arrived?'Try an incoming email':'Reset demo'};
'''

def frame(direction,body):
    title,note=notes[direction]
    return f'''<!doctype html><html lang="en" class="{direction}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Standalone portfolio design exploration, direction {direction.upper()}"><title>{title} — Rizki portfolio</title><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 40 40%27%3E%3Ctext y=%2730%27 font-size=%2730%27%3Ear%3C/text%3E%3C/svg%3E"><style>{CSS}</style></head><body><a class="skip" href="#main">Skip to content</a>{body}<footer class="foot wrap"><span>Always building. Always learning.</span><span>© 2026 Achmad Rizki Ramadhan</span></footer><details class="note" lang="id"><summary>{title}</summary><p>{note}</p><small>Mockup eksplorasi · proyek konsep diberi label.</small></details><dialog aria-labelledby="dialog-title"><div class="dialog-top"><h2 id="dialog-title"></h2><button class="icon" id="close-dialog" aria-label="Close dialog">×</button></div><div id="dialog-content"></div></dialog><script>{JS}</script></body></html>'''

header=f'<header class="top wrap"><a class="brand" href="#main" aria-label="Rizki portfolio">ar<span>.</span></a><span class="top-note">A personal space</span><div class="tools">{theme}</div></header>'
a_entries=''
for p in projects:
    a_entries+=f'''<article class="feed-entry project"><div class="project-meta">{'⌖ Featured project' if p['id']=='mail' else '<span class="demo">Concept project</span>'}</div><div class="post-by"><img src="{avatar}" alt="" width="28" height="28"><span>Achmad Rizki Ramadhan</span></div><h3>{p['name']}</h3><p>{p['desc']}</p><div style="margin-top:20px">{p['art']}</div>{tags(p)}{explore(p)}</article>'''
a=header+f'<main id="main" class="wrap shell">{profile}{nav}<section data-panel="projects" aria-label="Projects">{a_entries}<div class="feed-end">You’ve seen all 3 projects.</div></section>{alternate()}</main>'
(ROOT/'mockups/direction-a.html').write_text(frame('a',a))

p=projects[0]
b_featured=f'''<article class="featured project">{mail}<div class="project-info"><div class="project-meta">Featured project <span>Open source</span></div><div class="project-title-row"><h3>Mailriz</h3>{explore(p)}</div><p>{p['desc']}</p>{tags(p)}<div class="role-line">Custom-domain email · Application & cloud infrastructure</div></div></article>'''
b_cards=''.join(f'''<article class="compact project">{p['art']}<div class="project-info"><div class="project-meta"><span class="demo">Concept project</span></div><h3>{p['name']}</h3><p>{p['desc']}</p>{tags(p)}{explore(p)}</div></article>''' for p in projects[1:])
b=header+f'''<main id="main" class="wrap shell">{profile}<div>{nav}<section data-panel="projects" aria-label="Selected work"><div class="section-heading"><div><h2>Selected work</h2><p>From the interface to the infrastructure behind it.</p></div></div>{b_featured}<div class="more-work">{b_cards}</div><div class="latest"><div><span class="small muted">From the notebook · Sample writing</span><h3>Small systems, good habits.</h3></div><button class="text-btn" data-modal="writing">Read the note ↗</button></div></section>{alternate()}</div></main>'''
(ROOT/'mockups/direction-b.html').write_text(frame('b',b))

inbox='''<div class="inbox-app"><div class="inbox-top"><strong>✉ mailriz</strong><small id="mail-count">3 messages</small></div><div class="email-row" id="new-mail" hidden><span>H</span><div><strong>A new idea to build together</strong><small>hello@your.domain</small></div><time>Now</time></div><div class="email-row"><span>W</span><div><strong>Your deployment is ready</strong><small>work@your.domain</small></div><time>09:42</time></div><div class="email-row"><span>S</span><div><strong>Your order is on its way</strong><small>shop@your.domain</small></div><time>09:18</time></div><div class="email-row"><span>H</span><div><strong>A note from the community</strong><small>hello@your.domain</small></div><time>08:30</time></div><div class="inbox-footer"><span class="status">✓ Connected</span><button class="text-btn" id="simulate-mail">Try an incoming email</button></div></div><p id="mail-status" class="small muted" role="status" style="text-align:center;margin:15px auto 0">All aliases connected</p>'''
c_header=f'<header class="top wrap"><a class="brand" href="#main" aria-label="Rizki portfolio">ar<span>.</span></a>{nav}<div class="tools"><button class="btn" data-modal="contact">Let’s connect ↗</button>{theme}</div></header>'
c=c_header+f'''<main id="main" class="wrap"><section data-panel="projects" aria-label="Working studio"><div class="hero"><div><h1>From interface<br>to infrastructure.</h1><p>I build applications and the cloud systems behind them.<br>Here’s a closer look at how the pieces come together.</p></div><div class="hero-aside"><div class="profile-mini"><img class="avatar" src="{avatar}" alt="Achmad Rizki Ramadhan" width="52" height="52"><div><strong>Achmad Rizki Ramadhan</strong><span>Fullstack & cloud · Yogyakarta</span></div></div>{actions}</div></div><div class="bench"><div class="project-picker" aria-label="Choose a project"><p class="picker-caption">On the workbench</p><button class="pick" data-pick="mail" aria-pressed="true"><span class="pick-icon" aria-hidden="true">✉</span><span><strong>Mailriz</strong><small>Custom-domain email</small></span></button><button class="pick" data-pick="storage" aria-pressed="false"><span class="pick-icon" aria-hidden="true">▱</span><span><strong>Cloud drive</strong><small>Concept project</small></span></button><button class="pick" data-pick="agent" aria-pressed="false"><span class="pick-icon" aria-hidden="true">⌘</span><span><strong>Agent relay</strong><small>Concept project</small></span></button><p class="picker-note">Pick a project to look inside. Each preview is a small illustration of the idea.</p></div><div class="bench-view"><div class="bench-bar"><span id="stage-label">Interactive inbox concept</span><span class="window-dots" aria-hidden="true"><i></i><i></i><i></i></span></div><div class="stage" data-stage="mail">{inbox}</div><div class="stage" data-stage="storage" hidden>{storage}</div><div class="stage" data-stage="agent" hidden>{terminal}</div><div class="bench-info"><div><h2 id="bench-title">Mailriz</h2><p id="bench-desc">Persistent email aliases on your own domain, built on Cloudflare.</p></div><button class="btn primary" id="bench-explore" data-project="mail">Explore project ↗</button></div></div></div><span id="selection-status" class="small muted" role="status"></span><div class="principles"><article><h3>The interface</h3><p>Make the next step clear. Give people a familiar way to do what they came for.</p></article><article><h3>The infrastructure</h3><p>Connect the services behind the screen. Keep the system understandable.</p></article><article><h3>The working habit</h3><p>Build something useful, see how it behaves, and improve the parts that matter.</p></article></div></section>{alternate()}</main>'''
(ROOT/'mockups/direction-c.html').write_text(frame('c',c))
print('Created three standalone mockups.')
